import i18n from '@dhis2/d2-i18n'
import { useConfig, useDataQuery } from '@dhis2/app-runtime'
import { CircularLoader, NoticeBox } from '@dhis2/ui'
import React, { useState } from 'react'
import { useParams } from 'react-router-dom'
import { Form } from 'react-final-form'
import { ReportDefaultLayout, HTMLReport } from '../../../components'
import type { GeneratedParams } from '../../../components'
import type { DynamicResourceQuery, QueryVariables } from '@/types/query'
import { ParametersSelector } from './parametersSelector/ParametersSelector'
import { ReportInfoQueryResponse, queryFields } from './types'
import {
    getStandardReportsContextSnapshot,
    useUserContext,
} from '../../../context'

const REPORT_INFO_QUERY: { report: DynamicResourceQuery } = {
    report: {
        resource: 'reports',
        id: ({ id }) => id,
        params: {
            paging: false,
            fields: queryFields,
        },
    },
}

type ReportFormValues = {
    orgUnit?: string
    period?: string
}

// fall back as parameter selection is another PR
const DEV_FALLBACK_PARAMS = {
    orgUnit: 'Rp268JB6Ne4',
    period: '202601',
}

const REPORTS_GET = {
    reportHTML: {
        resource: 'reports',
        id: ({ id }: QueryVariables) => `${id}/data.html`,
        params: ({ orgUnit, period, t }: QueryVariables) => ({
            t,
            ou: orgUnit,
            pe: period,
        }),
    },
}

type ReportHTMLQueryResponse = {
    reportHTML: string
}

export const StandardReportView = () => {
    const { reportId } = useParams()
    // `calendar` is present on the real DHIS2 systemInfo response but
    // missing from this version of @dhis2/app-service-config's SystemInfo
    // type (same gap worked around in useFixedPeriods.ts)
    const calendar: string =
        (useConfig().systemInfo as { calendar?: string } | undefined)
            ?.calendar ?? 'gregory'

    const [generatedParams, setGeneratedParams] = useState<GeneratedParams>({})
    // Read once on mount; kept in state to avoid recalculation. Refreshed
    // to the just-submitted values once a report fetch completes

    const [initialValues, setInitialValues] = useState(
        getStandardReportsContextSnapshot(calendar)
    )
    const { loading, error, data } = useDataQuery<ReportInfoQueryResponse>(
        REPORT_INFO_QUERY,
        { variables: { id: reportId } }
    )
    const {
        refetch: getHTML,
        loading: loadingHTML,
        error: errorHTML,
        data: reportHTML,
    } = useDataQuery<ReportHTMLQueryResponse>(REPORTS_GET, {
        variables: { id: reportId },
        lazy: true,
    })
    const { canAdd, canDelete } = useUserContext()
    if (loading) {
        return <CircularLoader />
    }
    const { report } = data ?? { report: undefined }
    if (error || !reportId || !report) {
        return (
            <NoticeBox error title={i18n.t('Error loading requested report')} />
        )
    }

    return (
        <Form
            initialValues={initialValues}
            onSubmit={async (values: ReportFormValues) => {
                const fetchedAt = Number(new Date())
                // orgUnit param is a path, rather than an id
                const orgUnitId = values?.orgUnit?.split('/')?.at(-1)
                const orgUnit = orgUnitId ?? DEV_FALLBACK_PARAMS.orgUnit
                await getHTML({
                    orgUnit,
                    period: values.period,
                    t: fetchedAt,
                })
                // set once getHTML succeeds
                setGeneratedParams({
                    timestamp: fetchedAt,
                    orgUnit,
                    period: values?.period ?? DEV_FALLBACK_PARAMS.period,
                })
                setInitialValues(values)
            }}
            render={({ handleSubmit }) => (
                <ReportDefaultLayout
                    currentLocationString={report.displayName}
                    ParametersSelector={<ParametersSelector report={report} />}
                    ReportContent={
                        <HTMLReport
                            html={reportHTML?.reportHTML}
                            loading={loadingHTML}
                            error={errorHTML}
                        />
                    }
                    isEmpty={!reportHTML && !loadingHTML && !errorHTML}
                    onSubmit={handleSubmit}
                    additionalPath={
                        canAdd || canDelete
                            ? {
                                  location: '/standardReports/manage',
                                  text: i18n.t('Manage'),
                              }
                            : undefined
                    }
                    reportName={report.displayName}
                    generatedParams={generatedParams}
                />
            )}
        ></Form>
    )
}
