import { periodTypes } from '@dhis2/multi-calendar-dates'

export type MultiCalendarPeriodType = (typeof periodTypes)[number]

export const PERIODS_ORDER = [
    'Daily',
    'Weekly',
    'WeeklyWednesday',
    'WeeklyThursday',
    'WeeklySaturday',
    'WeeklySunday',
    'BiWeekly',
    'Monthly',
    'BiMonthly',
    'Quarterly',
    'QuarterlyNov',
    'SixMonthly',
    'SixMonthlyApril',
    'SixMonthlyNov',
    'Yearly',
    'FinancialApril',
    'FinancialJuly',
    'FinancialOct',
    'FinancialNov',
]

// keyed by the DHIS2 periodTypes API's "name" field, as returned (not
// uppercased) - e.g. "FinancialApril", "WeeklyWednesday"
export const PERIOD_TYPE_NAME_MAPPING: Record<string, MultiCalendarPeriodType> =
    {
        FinancialApril: 'FYAPR',
        FinancialAug: 'FYAUG',
        FinancialFeb: 'FYFEB',
        FinancialJuly: 'FYJUL',
        FinancialNov: 'FYNOV',
        FinancialOct: 'FYOCT',
        FinancialSep: 'FYSEP',
        SixMonthlyApril: 'SIXMONTHLYAPR',
        WeeklyFriday: 'WEEKLYFRI',
        WeeklySaturday: 'WEEKLYSAT',
        WeeklySunday: 'WEEKLYSUN',
        WeeklyThursday: 'WEEKLYTHU',
        WeeklyWednesday: 'WEEKLYWED',
    }

const SUPPORTED_PERIOD_TYPES: ReadonlySet<string> = new Set(periodTypes)

// looks up the DHIS2 periodTypes API name directly in the mapping first;
// only uppercases it as a fallback for names that already match directly
// (e.g. "Monthly" -> "MONTHLY"). Returns undefined for period types with no
// equivalent (e.g. "TwoYearly")
export const toMultiCalendarPeriodType = (
    apiPeriodType: string
): MultiCalendarPeriodType | undefined => {
    const mapped = PERIOD_TYPE_NAME_MAPPING[apiPeriodType]
    if (mapped) {
        return mapped
    }
    const uppercased = apiPeriodType.toUpperCase()
    return SUPPORTED_PERIOD_TYPES.has(uppercased)
        ? (uppercased as MultiCalendarPeriodType)
        : undefined
}
