import i18n from '@dhis2/d2-i18n'
import { useDataQuery } from '@dhis2/app-runtime'
import { Radio } from '@dhis2/ui'
import React, { useCallback, useState } from 'react'
import { useField } from 'react-final-form'
import { Report } from '../types'
import { usePeriod } from '../../../../context'
import { ParameterItem } from '@/components'
import { OrgUnitSelector } from './OrgUnitSelector'
import { RelativePeriodSelector } from './RelativePeriods'
import { CustomFixedPeriodSelector } from './fixedPeriods/CustomFixedPeriodSelector'
import {
    PERIODS_ORDER,
    toMultiCalendarPeriodType,
} from './fixedPeriods/periodTypeMapping'
import styles from './ParametersSelector.module.css'

const PERIOD_CATEGORIES = {
    FIXED: { value: 'fixed', label: i18n.t('Fixed period') },
    RELATIVE: { value: 'relative', label: i18n.t('Relative period') },
}

const PERIOD_TYPES_QUERY = {
    periodTypes: {
        resource: 'periodTypes',
    },
}

type PeriodTypesQueryResponse = {
    periodTypes: {
        periodTypes: Array<{
            name?: string
            displayName?: string
        }>
    }
}

const PeriodsSelector = ({ report }: { report: Report }) => {
    const { data, loading, error } =
        useDataQuery<PeriodTypesQueryResponse>(PERIOD_TYPES_QUERY)
    const periodTypes = (data?.periodTypes?.periodTypes ?? [])
        .filter(
            (
                periodType
            ): periodType is { name: string; displayName?: string } =>
                !!periodType.name
        )
        // sort based on PERIODS_ORDER
        .sort((a, b) => {
            const indexA = PERIODS_ORDER.indexOf(a.name)
            const indexB = PERIODS_ORDER.indexOf(b.name)
            if (indexA === -1) {
                return indexB === -1 ? 0 : 1
            }
            if (indexB === -1) {
                return -1
            }
            return indexA - indexB
        })
        // map to upper case (or custom mapping) expected by multicalendar-dates generator
        .map(({ displayName, name }) => ({
            label: displayName ?? name,
            value: toMultiCalendarPeriodType(name) ?? name.toUpperCase(),
        }))

    const { input: periodInput, meta: periodMeta } = useField('period', {
        subscription: { value: true },
    })
    // The relative periods this report allows, so an initial period value
    // (e.g. from the URL) can be recognised as relative rather than fixed.
    const validRelativePeriods = Object.entries(report.relativePeriods)
        .filter(([, value]) => value)
        .map(([key]) => key)
    const [periodCategory, setPeriodCategory] = useState<string>(() =>
        periodInput.value && validRelativePeriods.includes(periodInput.value)
            ? PERIOD_CATEGORIES.RELATIVE.value
            : PERIOD_CATEGORIES.FIXED.value
    )
    const [, setPeriod] = usePeriod()

    const handlePeriodCategoryChange = useCallback(
        (s: string) => {
            setPeriod(undefined)
            periodInput.onChange(undefined)
            setPeriodCategory(s)
        },
        [setPeriod, periodInput.onChange]
    )

    if (!report.reportParams.reportingPeriod) {
        return null
    }
    return (
        <>
            <div className={styles.periodModeRow}>
                <Radio
                    checked={periodCategory === PERIOD_CATEGORIES.FIXED.value}
                    label={PERIOD_CATEGORIES.FIXED.label}
                    name="radio-fixed"
                    onChange={() => {
                        handlePeriodCategoryChange(
                            PERIOD_CATEGORIES.FIXED.value
                        )
                    }}
                    value={PERIOD_CATEGORIES.FIXED.value}
                />
                <Radio
                    checked={
                        periodCategory === PERIOD_CATEGORIES.RELATIVE.value
                    }
                    label={PERIOD_CATEGORIES.RELATIVE.label}
                    name="radio-relative"
                    onChange={() => {
                        handlePeriodCategoryChange(
                            PERIOD_CATEGORIES.RELATIVE.value
                        )
                    }}
                    value={PERIOD_CATEGORIES.RELATIVE.value}
                />
            </div>
            {periodCategory === PERIOD_CATEGORIES.RELATIVE.value && (
                <RelativePeriodSelector report={report} />
            )}
            {periodCategory === PERIOD_CATEGORIES.FIXED.value &&
                !error &&
                !loading && (
                    <CustomFixedPeriodSelector
                        periodTypes={periodTypes}
                        periodTypesLoading={loading}
                    />
                )}
        </>
    )
}

export const ParametersSelector = ({ report }: { report: Report }) => {
    if (!report) {
        return null
    }
    return (
        <>
            {!report.reportParams.organisationUnit &&
                !report.reportParams.reportingPeriod && (
                    <p className={styles.help}>
                        {i18n.t(
                            'No parameters available. Period and org unit are set by the report.'
                        )}
                    </p>
                )}
            {report.reportParams.organisationUnit && (
                <ParameterItem title={i18n.t('Organisation unit')}>
                    <OrgUnitSelector />
                </ParameterItem>
            )}
            {report.reportParams.reportingPeriod && (
                <ParameterItem title={i18n.t('Period')}>
                    <PeriodsSelector report={report} />
                </ParameterItem>
            )}
        </>
    )
}
