import { useAlert, useDataMutation } from '@dhis2/app-runtime'
import i18n from '@dhis2/d2-i18n'
import { useNavigate } from 'react-router-dom'
import { ReportFormValues, StoredReport, toPayload } from './reportFormValues'

export const MANAGE_PATH = '/standardReports/manage'

type Mutation = Parameters<typeof useDataMutation>[0]
type Variables = { report: Awaited<ReturnType<typeof toPayload>> }

const CREATE_MUTATION = {
    resource: 'reports',
    type: 'create',
    data: ({ report }: Variables) => report,
} as unknown as Mutation

// Reports can't be PATCHed, so an update is a full PUT of the whole report
const UPDATE_MUTATION = {
    resource: 'reports',
    type: 'replace',
    id: ({ report }: Variables) => report.id,
    data: ({ report }: Variables) => report,
} as unknown as Mutation

export const useSaveReport = (existingReport?: StoredReport) => {
    const navigate = useNavigate()
    const { show: showSaved } = useAlert(
        existingReport
            ? i18n.t('The report has been updated')
            : i18n.t('The report has been created'),
        { success: true }
    )
    const [mutate, { loading, error }] = useDataMutation(
        existingReport ? UPDATE_MUTATION : CREATE_MUTATION,
        {
            onComplete: () => {
                showSaved()
                navigate(MANAGE_PATH)
            },
        }
    )

    const save = async (values: ReportFormValues) => {
        const report = await toPayload(values, existingReport)
        mutate({ report })
    }

    return { save, loading, error }
}
