export const FLATTENED_RELATIVE_PERIODS = Object.values(
    RELATIVE_PERIODS.reduce((acc, group) => {
        group.options.forEach((period) => {
            acc[period.value] = {
                value: period.value,
                label: period.label,
            }
        })
        return acc
    }, {} as Record<string, { value: string; label: string }>)
)
