import { OrganisationUnitTree } from '@dhis2/ui'
import React, { useCallback } from 'react'
import { useField } from 'react-final-form'
import { useOrgUnit, useUserContext } from '../../../../context'
import styles from './OrgUnitSelector.module.css'

export const OrgUnitSelector = () => {
    const { organisationUnits: rootOrgUnits } = useUserContext()
    const { input: orgUnitInput } = useField('ou', {
        subscription: { value: true },
    })
    const [, setOrgUnit] = useOrgUnit()

    const handleChange = useCallback(
        ({ selected }: { selected: string[] }) => {
            orgUnitInput.onChange(selected)
            setOrgUnit(selected[0])
        },
        [orgUnitInput.onChange]
    )

    return (
        <div className={styles.treeBox}>
            <OrganisationUnitTree
                roots={rootOrgUnits}
                singleSelection={true}
                onChange={handleChange}
                selected={orgUnitInput.value ? orgUnitInput.value : []}
                initiallyExpanded={rootOrgUnits}
            />
        </div>
    )
}
