import { useConfig, useDataQuery } from '@dhis2/app-runtime'
import i18n from '@dhis2/d2-i18n'
import { Button } from '@dhis2/ui'
import React from 'react'
import { useFormState } from 'react-final-form'
import { Breadcrumbs } from './Breadcrumbs'
import { EmptyState } from './EmptyState'
import styles from './ReportDefaultLayout.module.css'
import { createFixedPeriodFromPeriodId } from '@dhis2/multi-calendar-dates'
import { useUserContext } from '@/context'
import type { DynamicResourceQuery, QueryVariables } from '@/types/query'

export type GeneratedParams = {
    timestamp?: number
    period?: string
    orgUnit?: string
}

// not exported by @dhis2/multi-calendar-dates, so derived structurally from
// a function that uses it
type SupportedCalendar = Parameters<
    typeof createFixedPeriodFromPeriodId
>[0]['calendar']

const createdLabel = (timestamp: number, locale = 'en') =>
    i18n.t('Report created {{- when}}', {
        when: new Date(timestamp).toLocaleString(locale, {
            day: '2-digit',
            month: '2-digit',
            year: '2-digit',
            hour: '2-digit',
            minute: '2-digit',
        }),
    })

/*
 * reportName - period - orgUnit - timestamp, skipping whichever of these
 * aren't known yet. Only IDs are available for period/orgUnit for now, not
 * their display names.
 */

// The query engine calls `id` with whatever variables useDataQuery/refetch
// were given, merged together - QueryVariables (an index signature) is the
// type it actually promises to pass. A narrower object type such as
// `{ id?: string }` looks stronger but happens to typecheck for the wrong
// reason (the property being optional lets it slide); it stops working the
// moment `id` is required, so QueryVariables is used here too.
const ORG_UNIT_NAME_QUERY: { organisationUnits: DynamicResourceQuery } = {
    organisationUnits: {
        resource: 'organisationUnits',
        id: ({ id }: QueryVariables) => id ?? '',
        params: {
            fields: 'displayName',
        },
    },
}

type OrgUnitNameQueryResponse = {
    organisationUnits: {
        displayName: string
    }
}

const SummaryLine = ({
    reportName,
    generatedParams,
}: {
    reportName?: string
    generatedParams: GeneratedParams
}) => {
    const { period, orgUnit, timestamp } = generatedParams
    const { keyUiLocale } = useUserContext()
    const { data, loading } = useDataQuery<OrgUnitNameQueryResponse>(
        ORG_UNIT_NAME_QUERY,
        { variables: { id: orgUnit } }
    )

    // `calendar` is present on the real DHIS2 systemInfo response but missing
    // from this version of @dhis2/app-service-config's SystemInfo type
    const calendar: SupportedCalendar =
        ((useConfig().systemInfo as { calendar?: string } | undefined)
            ?.calendar as SupportedCalendar) ?? 'gregory'
    const periodName = period
        ? createFixedPeriodFromPeriodId({
              periodId: period,
              calendar,
          })?.displayName
        : undefined
    const orgUnitName = data?.organisationUnits?.displayName ?? orgUnit
    const summaryText =
        !loading &&
        [
            reportName,
            periodName,
            orgUnitName,
            timestamp !== undefined
                ? createdLabel(timestamp, keyUiLocale)
                : undefined,
        ]
            .filter(Boolean)
            .join(' · ')
    return (
        <div className={styles.summary}>
            <p className={styles.summaryLine}>{summaryText}</p>
        </div>
    )
}

const ReportContainer = ({
    ReportContent,
    isEmpty,
    generatedParams,
    reportName,
    onSubmit,
}: {
    ReportContent: React.ReactNode
    isEmpty: boolean
    generatedParams?: GeneratedParams
    reportName?: string
    onSubmit: () => void
}) => {
    const { dirty: isDirty } = useFormState({ subscription: { dirty: true } })
    return (
        <div className={styles.reportContainer}>
            {isDirty && (
                <span className={styles.staleBadge}>
                    {i18n.t('Not updated with the latest options')}
                    <button
                        type="button"
                        className={styles.staleAction}
                        onClick={onSubmit}
                    >
                        {i18n.t('Update')}
                    </button>
                </span>
            )}
            {!isEmpty && generatedParams && (
                <SummaryLine
                    generatedParams={generatedParams}
                    reportName={reportName}
                />
            )}
            {isEmpty ? <EmptyState /> : ReportContent}
        </div>
    )
}

export const ReportDefaultLayout = ({
    ParametersSelector,
    ReportContent,
    currentLocationString,
    isEmpty,
    additionalPath,
    generatedParams,
    reportName,
    onSubmit,
}: {
    ParametersSelector: React.ReactNode
    ReportContent: React.ReactNode
    currentLocationString: string
    isEmpty: boolean
    additionalPath?: {
        text: string
        location: string
    }
    generatedParams?: GeneratedParams
    reportName?: string
    onSubmit: () => void
}) => {
    return (
        <>
            <Breadcrumbs
                currentLocation={currentLocationString}
                additionalPath={additionalPath}
            />
            <div className={styles.layout}>
                <div className={styles.parametersSelector}>
                    <div>params selector</div>
                    {ParametersSelector}
                    <Button type="submit" primary onClick={onSubmit}>
                        {i18n.t('Get report')}
                    </Button>
                </div>
                <ReportContainer
                    ReportContent={ReportContent}
                    isEmpty={isEmpty}
                    generatedParams={generatedParams}
                    reportName={reportName}
                    onSubmit={onSubmit}
                />
            </div>
        </>
    )
}
