import { DEFAULT_CACHE_STRATEGY } from './options'

type CheckedMap = Record<string, boolean>

/*
 * `reportParams` and `relativePeriods` keep the API's shape ({ key: boolean })
 * so checkbox fields can bind to them directly, e.g. `relativePeriods.thisMonth`.
 */
export type ReportFormValues = {
    name?: string
    code?: string
    designFile?: File[]
    // Edit only: the current design stays until the user removes it
    keepCurrentDesign?: boolean
    cacheStrategy?: string
    reportParams?: CheckedMap
    relativePeriods?: CheckedMap
}

/*
 * A report as returned by `fields=:owner,relativePeriods`. Only the properties
 * the form edits are typed; the rest (sharing, translations, ...) are passed
 * back untouched, because the API only accepts a full PUT for reports.
 */
export type StoredReport = {
    id: string
    name: string
    type?: string
    code?: string
    designContent?: string
    cacheStrategy?: string
    reportParams?: CheckedMap
    relativePeriods?: CheckedMap
    [key: string]: unknown
}

export const NEW_REPORT_VALUES: ReportFormValues = {
    cacheStrategy: DEFAULT_CACHE_STRATEGY,
}

export const toFormValues = (report: StoredReport): ReportFormValues => ({
    name: report.name,
    code: report.code,
    keepCurrentDesign: Boolean(report.designContent),
    cacheStrategy: report.cacheStrategy ?? DEFAULT_CACHE_STRATEGY,
    reportParams: report.reportParams,
    relativePeriods: report.relativePeriods,
})

export const toPayload = async (
    values: ReportFormValues,
    existingReport?: StoredReport
) => {
    const designFile = values.designFile?.[0]

    return {
        ...existingReport,
        type: 'HTML',
        name: values.name,
        // Set explicitly (not spread) so a cleared field clears the stored value
        code: values.code ?? null,
        cacheStrategy: values.cacheStrategy,
        reportParams: values.reportParams,
        relativePeriods: values.relativePeriods,
        // No new file keeps the current design
        designContent: designFile
            ? await designFile.text()
            : existingReport?.designContent,
    }
}
