import i18n from '@dhis2/d2-i18n'
import { NoticeBox } from '@dhis2/ui'
import React from 'react'
import { useUserContext } from '../../../context'
import { FormColumn, FormPage } from '../form/FormPage'
import { StandardReportForm } from '../form/StandardReportForm'

export const StandardReportAdd = () => {
    const { canAdd } = useUserContext()

    return (
        <FormPage title={i18n.t('New standard report')}>
            {canAdd ? (
                <StandardReportForm />
            ) : (
                <FormColumn>
                    <NoticeBox warning>
                        {i18n.t('You do not have access to create reports')}
                    </NoticeBox>
                </FormColumn>
            )}
        </FormPage>
    )
}
