import { useCallback } from 'react'
import {
    StringParam,
    useQueryParams,
    useQueryParam,
    decodeQueryParams,
    searchStringToObject,
} from 'use-query-params'
import { getStartOfYearInCalendarString } from './getNow'

const STANDARD_REPORTS_SCHEMA = {
    period: StringParam,
    ou: StringParam,
}

const DATA_SET_REPORTS_SCHEMA = {
    period: StringParam,
    ou: StringParam,
    dataSet: StringParam,
}

const NAVIGATION_SCHEMA = {
    searchTerm: StringParam,
}

const PARAMS_SCHEMA = {
    ...STANDARD_REPORTS_SCHEMA,
    ...DATA_SET_REPORTS_SCHEMA,
    ...NAVIGATION_SCHEMA,
}

// reads current query parameters imperatively to avoid re-rendering

const getContextSnapshot = (schema: Record<string, any>) => {
    const [, searchString = ''] = window.location.hash.split('?')
    return decodeQueryParams(schema, searchStringToObject(`?${searchString}`))
}

export const getStandardReportsContextSnapshot = (calendar = 'gregory') => {
    const parametersSnapshot = getContextSnapshot(STANDARD_REPORTS_SCHEMA)
    parametersSnapshot.ou = parametersSnapshot.ou ? [parametersSnapshot.ou] : []
    // if there is no period, we initialise to 1 January of current year for fixed period
    return parametersSnapshot
}

export const getDataSetReportsContextSnapshot = () => {
    return getContextSnapshot(DATA_SET_REPORTS_SCHEMA)
}

export const usePeriod = () => {
    return useQueryParam('period', PARAMS_SCHEMA.period)
}
export const useOrgUnit = () => {
    return useQueryParam('ou', PARAMS_SCHEMA.ou)
}

export const useStandardReportsContextSelection = () => {
    return useQueryParams(PARAMS_SCHEMA)
}

export const useClearEntireSelection = () => {
    const [, setSelectionContext] = useStandardReportsContextSelection()

    return useCallback(() => {
        setSelectionContext({
            period: undefined,
            ou: undefined,
        })
    }, [setSelectionContext])
}
